+    if (port < 0 || port >= MAX_PADS || !(bt_dev.status & DS34BT_STATE_USB_AUTHORIZED))
+        return;
+
+    WaitSema(bt_dev.hid_sema);
+
+    if (pad_status_check(DS34BT_STATE_RUNNING, port)) {
