+            if (*q == '=') {
+                int len = 0;
+
+                q++;
+                while (*q == ' ' || *q == '\t')
+                    q++;
+                if (strncmp(q, "cdrom:", 6) == 0)
+                    q += 6;
+                while (*q == '\\')
+                    q++;
+
+                while (q[len] != '\0' && q[len] != ';' && q[len] != ' ' &&
+                       q[len] != '\t' && q[len] != '\r' && q[len] != '\n')
+                    len++;
+
+                if (len <= 0 || len >= max)
+                    return -7;
+
+                memcpy(out, q, len);
+                out[len] = '\0';
+                return 0;
+            }
+        }
+
+        while (*p != '\0' && *p != '\n')
+            p++;
+        if (*p == '\n')
